const DE = 'de';
const EN = 'en';

export function haloLanguage(hass) {
  const raw = String(hass?.locale?.language || hass?.language || navigator.language || 'en').toLowerCase();
  return raw.startsWith('de') ? DE : EN;
}

export function haloLocale(hass) {
  return haloLanguage(hass) === DE ? 'de-DE' : 'en-US';
}

