export function translateHaloText(value, hass) {
  if (haloLanguage(hass) === DE || value == null) return String(value ?? '');
  let out = String(value);
  for (const [de,en] of EN_REPLACEMENTS) out = out.split(de).join(en);
  return out;
}

export function localizeHaloDom(root, hass) {
  if (!root || haloLanguage(hass) === DE) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes=[];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) {
    const next = translateHaloText(node.nodeValue, hass);
    if (next !== node.nodeValue) node.nodeValue = next;
  }
  const elements = root.querySelectorAll?.('*') || [];
  for (const el of elements) {
    for (const attr of ['title','placeholder','aria-label']) {
      if (el.hasAttribute?.(attr)) {
        const old = el.getAttribute(attr);
        const next = translateHaloText(old, hass);
        if (next !== old) el.setAttribute(attr,next);
      }
    }
  }
}

export function haloWeatherLabel(condition, hass) {
  const de = {
    sunny:'Sonnig','clear-night':'Klare Nacht',cloudy:'Bewölkt',partlycloudy:'Teilweise bewölkt',
    rainy:'Regen',pouring:'Starker Regen',lightning:'Gewitter','lightning-rainy':'Gewitter & Regen',
    snowy:'Schnee','snowy-rainy':'Schneeregen',fog:'Nebel',windy:'Windig','windy-variant':'Windig',hail:'Hagel',exceptional:'Außergewöhnlich'
  };
  const en = {
    sunny:'Sunny','clear-night':'Clear night',cloudy:'Cloudy',partlycloudy:'Partly cloudy',
    rainy:'Rain',pouring:'Heavy rain',lightning:'Thunderstorm','lightning-rainy':'Thunderstorm & rain',
    snowy:'Snow','snowy-rainy':'Sleet',fog:'Fog',windy:'Windy','windy-variant':'Windy',hail:'Hail',exceptional:'Exceptional'
  };
  const key=String(condition||'').toLowerCase();
  return (haloLanguage(hass)===DE?de:en)[key] || condition || (haloLanguage(hass)===DE?'Nicht verfügbar':'Unavailable');
}

export function haloPresenceLabel(state, hass) {
  const raw=String(state||'').trim();
  const lower=raw.toLowerCase();
  if (!raw || lower==='unknown' || lower==='unavailable') return haloLanguage(hass)===DE?'Nicht verfügbar':'Unavailable';
  if (lower==='home') return haloLanguage(hass)===DE?'Zuhause':'Home';
  if (lower==='not_home') return haloLanguage(hass)===DE?'Unterwegs':'Away';
  return raw;
}
